"use client"

import * as React from "react"

import { BotIcon, CheckIcon } from "@/components/icons"
import { AgentCodeBlock } from "@/registry/base-nova/ui/agent-code-block"
import { FileDiff } from "@/registry/base-nova/ui/file-diff"
import { Message, MessageAvatar, MessageBubble, MessageContent, MessageHeader, MessageList, MessageMarker, MessageMeta } from "@/registry/base-nova/ui/message"
import { ReasoningText } from "@/registry/base-nova/ui/reasoning-text"
import { StreamingResponse, type StreamingResponseStatus } from "@/registry/base-nova/ui/streaming-response"
import { TodoList } from "@/registry/base-nova/ui/todo-list"
import { ToolApproval } from "@/registry/base-nova/ui/tool-approval"
import { ToolResult, ToolResultOutput } from "@/registry/base-nova/ui/tool-result"

import { diffs, plan, summary, testLog, testSnippet } from "./data"

export type Turn = { id: string; text: string; reply?: string }

/** Assistant row: avatar plus a full-width column of agent blocks. */
function AgentTurn({ meta, children }: { meta: React.ReactNode; children: React.ReactNode }) {
  return (
    <Message from="assistant" className="items-start">
      <MessageAvatar className="mt-0.5">
        <BotIcon />
      </MessageAvatar>
      <div className="flex min-w-0 flex-1 flex-col gap-3">
        <MessageHeader className="mb-0 h-8">
          <span className="text-foreground">Tessel</span>
          <span aria-hidden>·</span>
          <span className="tabular-nums">{meta}</span>
        </MessageHeader>
        {children}
      </div>
    </Message>
  )
}

function useStream(text: string, run: boolean) {
  const [length, setLength] = React.useState(run ? 0 : text.length)
  const [status, setStatus] = React.useState<StreamingResponseStatus>(run ? "streaming" : "complete")
  React.useEffect(() => {
    if (!run) return
    let n = 0
    const id = window.setInterval(() => {
      n = Math.min(text.length, n + 4 + Math.floor(Math.random() * 6))
      setLength(n)
      if (n >= text.length) {
        window.clearInterval(id)
        setStatus("complete")
      }
    }, 28)
    return () => window.clearInterval(id)
  }, [text, run])
  return { text: text.slice(0, length), status }
}

function StreamedReply({ text, animate = true }: { text: string; animate?: boolean }) {
  const s = useStream(text, animate)
  return <StreamingResponse text={s.text} status={s.status} copyText={text} />
}

export function Conversation({ turns, working }: { turns: Turn[]; working: boolean }) {
  return (
    <MessageList className="mx-auto max-w-3xl">
      <MessageMarker>Today · 10:42</MessageMarker>
      <Message from="user">
        <MessageContent>
          <MessageBubble tone="primary">
            Invoices with fractional unit prices are coming out 1¢ high. INV-2045 is the one finance flagged. Can you find the cause
            and fix it?
          </MessageBubble>
          <MessageMeta>
            <CheckIcon /> 10:42
          </MessageMeta>
        </MessageContent>
      </Message>

      <AgentTurn meta="Worked for 1m 48s">
        <TodoList items={plan} title="Fix invoice rounding" defaultOpen />
        <ToolResult kind="terminal" tool="bash" title="Billing tests passed" status="success" duration={1.81} meta="exit 0" defaultOpen={false} copyText={testLog}>
          <ToolResultOutput>{testLog}</ToolResultOutput>
        </ToolResult>
        <FileDiff filename={diffs["invoice.ts"].filename} diff={diffs["invoice.ts"].diff} />
        <FileDiff filename={diffs["money.ts"].filename} diff={diffs["money.ts"].diff} defaultOpen={false} />
        <AgentCodeBlock filename="packages/billing/src/invoice.test.ts" code={testSnippet} highlightLines={[[9, 9]]} maxHeight={260} />
        <StreamedReply text={summary} />
        <ToolApproval
          tool="github.create_pull_request"
          title="Open a pull request?"
          description="Push fix/invoice-rounding and open a PR against main for review."
          risk="medium"
          defaultArgsOpen={false}
          args={{ repo: "acme/billing", head: "fix/invoice-rounding", base: "main", title: "Round line items to cents before tax", draft: false }}
        />
      </AgentTurn>

      {turns.map((t) => (
        <React.Fragment key={t.id}>
          <Message from="user" animateIn>
            <MessageContent>
              <MessageBubble tone="primary">{t.text}</MessageBubble>
            </MessageContent>
          </Message>
          {t.reply && (
            <AgentTurn meta="just now">
              <StreamedReply text={t.reply} />
            </AgentTurn>
          )}
        </React.Fragment>
      ))}

      {working && (
        <div className="flex h-8 items-center ps-11 text-sm">
          <ReasoningText phrases={["Reading the thread", "Checking the diff", "Drafting a reply"]} />
        </div>
      )}
    </MessageList>
  )
}

/* Scripted session for the agent workspace template. */

import type { TodoItem } from "@/registry/base-nova/ui/todo-list"

export const sessions = {
  today: [
    { id: "s1", title: "Fix invoice rounding", meta: "running" },
    { id: "s2", title: "Add Stripe webhook retries", meta: "2h" },
    { id: "s3", title: "Explain ledger reconcile", meta: "4h" },
  ],
  earlier: [
    { id: "s4", title: "Migrate tax rates to JSON", meta: "Mon" },
    { id: "s5", title: "Flaky e2e on checkout", meta: "Sun" },
    { id: "s6", title: "Bump Next to 15.5", meta: "Oct 9" },
  ],
}

export const plan: TodoItem[] = [
  { id: "1", title: "Reproduce the 1¢ drift on INV-2045", status: "done", meta: "1 failing test" },
  { id: "2", title: "Round line items before applying tax", status: "done", meta: "2 files" },
  { id: "3", title: "Run the billing test suite", status: "done", meta: "69 passed" },
  { id: "4", title: "Open a pull request against main", status: "in-progress" },
]

export const testLog = [
  "$ pnpm vitest run packages/billing",
  "",
  " RUN  v3.2.4 /repo/packages/billing",
  "",
  " ✓ src/invoice.test.ts (13 tests) 51ms",
  " ✓ src/tax/rates.test.ts (31 tests) 108ms",
  " ✓ src/webhooks/stripe.test.ts (9 tests) 197ms",
  " ✓ src/ledger/reconcile.test.ts (16 tests) 384ms",
  "",
  " Test Files  4 passed (4)",
  "      Tests  69 passed (69)",
  "   Duration  1.81s",
].join("\n")

export const invoiceDiff = `@@ -18,11 +18,14 @@ export function totalFor(invoice: Invoice) {
   const lines = invoice.lines.map((line) => {
-    const net = line.unitPrice * line.quantity
-    return { ...line, net }
+    // Round each line to cents first so tax is applied to what the customer sees.
+    const net = roundCents(line.unitPrice * line.quantity)
+    return { ...line, net }
   })

   const subtotal = sum(lines.map((l) => l.net))
-  const tax = subtotal * invoice.taxRate
-  return { subtotal, tax, total: subtotal + tax }
+  const tax = roundCents(subtotal * invoice.taxRate)
+  return { subtotal, tax, total: roundCents(subtotal + tax) }
 }
`

export const moneyDiff = `@@ -1,6 +1,11 @@
 export const CURRENCY = "USD"

+/** Banker's rounding to whole cents; avoids drift when summing many lines. */
+export function roundCents(value: number) {
+  return Math.round((value + Number.EPSILON) * 100) / 100
+}
+
 export function formatMoney(value: number) {
   return new Intl.NumberFormat("en-US", { style: "currency", currency: CURRENCY }).format(value)
 }
`

export const testSnippet = `it("rounds each line before tax (INV-2045)", () => {
  const invoice = makeInvoice({
    taxRate: 0.0825,
    lines: [
      { unitPrice: 19.99, quantity: 3 },
      { unitPrice: 4.333, quantity: 7 },
    ],
  })
  expect(totalFor(invoice).total).toBe(97.76)
})`

export const summary = `Fixed the 1¢ drift. Line items were summed at full precision and only the total was rounded, so invoices with fractional unit prices like **INV-2045** came out a cent high.

- Added \`roundCents()\` in \`lib/money.ts\` and applied it per line, to tax and to the total
- Added a regression test that reproduces INV-2045 exactly
- All **69** billing tests pass locally

Ready to push \`fix/invoice-rounding\` and open the PR when you approve it.`

export const diffs: Record<string, { filename: string; diff: string }> = {
  "invoice.ts": { filename: "packages/billing/src/invoice.ts", diff: invoiceDiff },
  "money.ts": { filename: "packages/billing/src/lib/money.ts", diff: moneyDiff },
}

"use client"

import { ChatIcon, PlusIcon, SettingsIcon } from "@/components/icons"
import {
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarItem,
  SidebarMenu,
} from "@/registry/base-nova/ui/animated-sidebar"
import { Badge } from "@/registry/base-nova/ui/badge"
import { Button } from "@/registry/base-nova/ui/button"

import { sessions } from "./data"

export function SessionNav({ active, onSelect }: { active: string; onSelect: (id: string) => void }) {
  const group = (label: string, list: typeof sessions.today) => (
    <SidebarGroup>
      <SidebarGroupLabel>{label}</SidebarGroupLabel>
      <SidebarMenu>
        {list.map((s) => (
          <SidebarItem
            key={s.id}
            icon={<ChatIcon />}
            label={s.title}
            isActive={active === s.id}
            onClick={() => onSelect(s.id)}
            badge={
              s.meta === "running" ? (
                <Badge size="sm" variant="primary">
                  Live
                </Badge>
              ) : undefined
            }
          />
        ))}
      </SidebarMenu>
    </SidebarGroup>
  )
  return (
    <>
      <SidebarHeader>
        <Button variant="secondary" size="sm" className="w-full">
          <PlusIcon data-icon="inline-start" />
          New session
        </Button>
      </SidebarHeader>
      <SidebarContent className="scrollbar-hover">
        {group("Today", sessions.today)}
        {group("Earlier", sessions.earlier)}
      </SidebarContent>
      <SidebarFooter>
        <SidebarMenu>
          <SidebarItem icon={<SettingsIcon />} label="Agent settings" />
        </SidebarMenu>
      </SidebarFooter>
    </>
  )
}

import { AgentWorkspace } from "@/registry/base-nova/templates/agent-workspace/agent-workspace"

export default function AgentPage() {
  return <AgentWorkspace />
}
